namespace Imotek.Domain.Properties;

/// <summary>A photo uploaded by the owner and kept in Imotek's own storage.</summary>
public sealed class PropertyImage
{
    public const int StorageKeyMaxLength = 300;
    public const int ContentTypeMaxLength = 50;

    // Required by EF Core.
    private PropertyImage()
    {
    }

    public Guid Id { get; private set; }

    /// <summary>Location in the file storage. Generated by the server, never taken from the client.</summary>
    public string StorageKey { get; private set; } = string.Empty;

    public string ContentType { get; private set; } = string.Empty;
    public long SizeBytes { get; private set; }
    public int SortOrder { get; private set; }
    public DateTime CreatedAt { get; private set; }

    public static PropertyImage Create(Guid id, string storageKey, string contentType, long sizeBytes, int sortOrder, DateTime utcNow) =>
        new()
        {
            Id = id,
            StorageKey = storageKey,
            ContentType = contentType,
            SizeBytes = sizeBytes,
            SortOrder = sortOrder,
            CreatedAt = utcNow,
        };
}
